css:
.lumibec-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #e6e9f5;
    background: radial-gradient(circle at 18% 0%, #1b1640 0%, #120f2e 45%, #0a0820 100%);
    border-radius: 18px;
}

.lumibec-container * {
    box-sizing: border-box;
}

.lumibec-header {
    text-align: center;
    padding: 30px 22px 26px;
    background: linear-gradient(135deg, #2a1d63 0%, #4322a6 50%, #7a1f8f 100%);
    color: #f4f1ff;
    border-radius: 16px;
    margin-bottom: 18px;
    box-shadow: 0 16px 40px rgba(67, 34, 166, 0.40);
    border: 1px solid rgba(168, 130, 255, 0.30);
}

.lumibec-header h1 {
    margin: 12px 0 12px;
    font-size: 2.5rem;
    font-weight: 800;
    letter-spacing: -0.5px;
    color: #ffffff;
    text-shadow: 0 0 22px rgba(0, 234, 197, 0.35);
}

.lumibec-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.3px;
    font-weight: 700;
    color: #00ead0;
    background: rgba(0, 234, 208, 0.10);
    border: 1px solid rgba(0, 234, 208, 0.42);
    padding: 5px 14px;
    border-radius: 999px;
}

.lumibec-subtitle {
    margin: 0 auto;
    max-width: 840px;
    font-size: 1rem;
    line-height: 1.6;
    color: #d4ccf2;
}

.lumibec-comms {
    display: flex;
    align-items: stretch;
    gap: 12px;
    margin-bottom: 18px;
}

.lumibec-comm {
    flex: 1;
    background: rgba(255, 255, 255, 0.04);
    border-radius: 14px;
    padding: 14px 18px;
    box-shadow: 0 4px 16px rgba(0, 0, 0, 0.30);
    border: 1px solid rgba(168, 130, 255, 0.18);
    display: flex;
    flex-direction: column;
    gap: 4px;
}

.lumibec-comm-render { border-left: 5px solid #ff5fa2; }
.lumibec-comm-narrative { border-left: 5px solid #ffb648; }
.lumibec-comm-gameplay { border-left: 5px solid #00ead0; }

.lumibec-comm-name {
    font-weight: 800;
    font-size: 1.02rem;
    color: #f0ecff;
}

.lumibec-comm-render .lumibec-comm-name { color: #ff7eb6; }
.lumibec-comm-narrative .lumibec-comm-name { color: #ffc266; }
.lumibec-comm-gameplay .lumibec-comm-name { color: #4ff0dd; }

.lumibec-comm-meta {
    font-size: 0.8rem;
    color: #a99fd0;
    line-height: 1.4;
}

.lumibec-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #b6abdd;
    margin-bottom: 16px;
    padding: 4px 4px;
}

.lumibec-period-counter #currentDay,
.lumibec-period-counter #maxPeriods {
    font-weight: 800;
    color: #00ead0;
}

.lumibec-round-name {
    background: rgba(0, 234, 208, 0.12);
    color: #4ff0dd;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
    border: 1px solid rgba(0, 234, 208, 0.30);
}

.lumibec-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #ffc266;
    background: rgba(255, 182, 72, 0.12);
    border: 1px solid rgba(255, 182, 72, 0.32);
    padding: 4px 12px;
    border-radius: 999px;
}

.lumibec-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.lumibec-status-card {
    background: rgba(255, 255, 255, 0.05);
    border-radius: 14px;
    padding: 16px 16px 14px;
    box-shadow: 0 6px 18px rgba(0, 0, 0, 0.32);
    border-top: 4px solid #7a4fff;
    border-left: 1px solid rgba(168, 130, 255, 0.14);
}

.lumibec-card-throughput { border-top-color: #00ead0; }
.lumibec-card-engagement { border-top-color: #ff5fa2; }
.lumibec-card-ttp { border-top-color: #ffb648; }
.lumibec-card-roi { border-top-color: #8a7bff; }

.lumibec-label {
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.7px;
    font-weight: 700;
    color: #9a8fc4;
}

.lumibec-value {
    font-size: 2.6rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #f0ecff;
    font-variant-numeric: tabular-nums;
}

.lumibec-card-throughput .lumibec-value { color: #00ead0; text-shadow: 0 0 18px rgba(0, 234, 208, 0.30); }
.lumibec-card-engagement .lumibec-value { color: #ff7eb6; }
.lumibec-card-ttp .lumibec-value { color: #ffc266; }
.lumibec-card-roi .lumibec-value { color: #b3a6ff; }

.lumibec-sublabel {
    font-size: 0.74rem;
    color: #8e84b6;
    line-height: 1.35;
}

.lumibec-card-throughput.lumibec-bad .lumibec-value { color: #ff5d5d; text-shadow: none; }
.lumibec-card-throughput.lumibec-good .lumibec-value { color: #4ff0dd; }
.lumibec-card-ttp.lumibec-bad .lumibec-value { color: #ff5d5d; }
.lumibec-card-roi.lumibec-good .lumibec-value { color: #4ff0dd; }
.lumibec-card-roi.lumibec-bad .lumibec-value { color: #ff5d5d; }

.lumibec-meters {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 12px;
    margin-bottom: 18px;
}

.lumibec-meter {
    display: flex;
    flex-direction: column;
    gap: 3px;
    background: rgba(255, 255, 255, 0.04);
    border: 1px solid rgba(168, 130, 255, 0.16);
    border-radius: 12px;
    padding: 10px 16px;
    font-weight: 700;
}

.lumibec-meter-label {
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    color: #9a8fc4;
}

.lumibec-meter span:last-child {
    font-size: 1.15rem;
    color: #00ead0;
    font-weight: 800;
    font-variant-numeric: tabular-nums;
}

.lumibec-meter.lumibec-meter-warn span:last-child { color: #ffc266; }
.lumibec-meter.lumibec-meter-bad span:last-child { color: #ff5d5d; }

.lumibec-briefing {
    display: flex;
    gap: 14px;
    background: rgba(255, 255, 255, 0.05);
    border-left: 5px solid #00ead0;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 6px 18px rgba(0, 0, 0, 0.28);
}

.lumibec-briefing-icon {
    font-size: 1.9rem;
    line-height: 1;
}

.lumibec-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #f0ecff;
    margin-bottom: 6px;
}

.lumibec-briefing-text {
    font-size: 0.95rem;
    line-height: 1.6;
    color: #c9c0ec;
}

.lumibec-briefing-text strong { color: #4ff0dd; }
.lumibec-briefing-text em { color: #ffc266; font-style: italic; }

.lumibec-controls {
    background: rgba(255, 255, 255, 0.05);
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    box-shadow: 0 6px 18px rgba(0, 0, 0, 0.28);
    border: 1px solid rgba(168, 130, 255, 0.14);
}

.lumibec-controls h3 {
    margin: 0 0 14px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #f0ecff;
    border-bottom: 2px solid rgba(168, 130, 255, 0.22);
    padding-bottom: 8px;
}

.lumibec-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #d4ccf2;
    margin: 14px 0 6px;
}

.lumibec-container select,
.lumibec-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #4a3f7a;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #1a1540;
    color: #ece8ff;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.lumibec-container select:focus,
.lumibec-container input[type="number"]:focus {
    outline: none;
    border-color: #00ead0;
    box-shadow: 0 0 0 3px rgba(0, 234, 208, 0.20);
}

.lumibec-container select option {
    background-color: #1a1540;
    color: #ece8ff;
}

.lumibec-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #00ead0;
}

.lumibec-range-readout {
    font-size: 0.86rem;
    font-weight: 700;
    color: #b6abdd;
    margin-top: 4px;
}

.lumibec-range-readout span:nth-child(2) {
    color: #00ead0;
    font-weight: 800;
}

.lumibec-range-note {
    color: #8e84b6;
    font-weight: 600;
    font-style: italic;
}

.lumibec-hint {
    font-size: 0.8rem;
    color: #8e84b6;
    margin-top: 6px;
    line-height: 1.4;
    font-style: italic;
}

.lumibec-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.lumibec-container .btn-primary {
    background: linear-gradient(135deg, #00ead0 0%, #5a3fff 100%);
    border: none;
    color: #0a0820;
    padding: 11px 26px;
    border-radius: 9px;
    box-shadow: 0 8px 22px rgba(0, 234, 208, 0.30);
}

.lumibec-container .btn-primary:hover {
    filter: brightness(1.08);
}

.lumibec-container .btn-outline-secondary {
    margin-left: 10px;
    border: 1px solid #4a3f7a;
    color: #b6abdd;
    background: transparent;
}

.lumibec-coach {
    background: linear-gradient(160deg, #1d1452 0%, #2a1546 100%);
    color: #d8d0f4;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 8px 22px rgba(0, 0, 0, 0.34);
    border: 1px solid rgba(168, 130, 255, 0.22);
}

.lumibec-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #ffc266;
    margin-bottom: 8px;
}

.lumibec-coach-body {
    font-size: 0.95rem;
    line-height: 1.6;
}

.lumibec-coach-body strong { color: #4ff0dd; }
.lumibec-coach-body em { color: #ffc266; font-style: italic; }

.lumibec-history,
.lumibec-chart {
    background: rgba(255, 255, 255, 0.05);
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 18px rgba(0, 0, 0, 0.28);
    border: 1px solid rgba(168, 130, 255, 0.14);
}

.lumibec-history h3,
.lumibec-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #f0ecff;
}

.lumibec-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #c9c0ec;
}

.lumibec-container table#usfHistoryTable th {
    background: rgba(0, 234, 208, 0.08);
    color: #4ff0dd;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid rgba(0, 234, 208, 0.24);
}

.lumibec-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid rgba(168, 130, 255, 0.12);
    color: #c9c0ec;
}

.lumibec-container table#usfHistoryTable tr:nth-child(even) td {
    background: rgba(255, 255, 255, 0.03);
}

.lumibec-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .lumibec-container {
        padding: 14px;
    }
    .lumibec-header h1 {
        font-size: 1.8rem;
    }
    .lumibec-comms {
        flex-direction: column;
    }
    .lumibec-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .lumibec-meters {
        grid-template-columns: 1fr;
    }
    .lumibec-value {
        font-size: 2.1rem;
    }
    .lumibec-clock {
        margin-left: 0;
    }
    .lumibec-period-counter {
        font-size: 0.88rem;
    }
    .lumibec-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}


/* ===== v1.1.0 FIX B - completion / innovation-board debrief scorecard (append-only, namespaced) ===== */
.cc-cm { padding: 12px 6px; text-align: center; font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif; }
.cc-cm-heading { font-size: 12px; letter-spacing: .08em; text-transform: uppercase; color: #7a8398; margin-bottom: 6px; }
.cc-cm-verdict { font-size: 22px; font-weight: 700; color: #eceff6; margin-bottom: 8px; }
.cc-cm-score { font-size: 16px; color: #eceff6; margin-bottom: 16px; }
.cc-cm-score strong { color: #4f9bd9; }
.cc-cm-sub { font-size: 11px; letter-spacing: .06em; text-transform: uppercase; color: #7a8398; margin-bottom: 8px; }
.cc-cm-targets { display: flex; flex-wrap: wrap; justify-content: center; gap: 8px; margin-bottom: 16px; }
.cc-cm-target { display: inline-flex; align-items: center; gap: 6px; padding: 6px 11px; border-radius: 20px; font-size: 13px; border: 1px solid transparent; }
.cc-cm-target.cc-cm-met { background: rgba(79,155,217,0.16); color: #8fc3ea; border-color: rgba(79,155,217,0.4); }
.cc-cm-target.cc-cm-missed { background: rgba(255,110,110,0.14); color: #ff9d9d; border-color: rgba(255,110,110,0.36); }
.cc-cm-tick { font-weight: 700; }
.cc-cm-metrics { display: flex; flex-wrap: wrap; justify-content: center; gap: 10px; margin-bottom: 16px; }
.cc-cm-metric { display: inline-flex; flex-direction: column; align-items: center; gap: 2px; padding: 9px 13px; background: rgba(120,135,175,0.12); border-radius: 8px; min-width: 92px; }
.cc-cm-metric span { font-size: 11px; letter-spacing: .03em; text-transform: uppercase; color: #7a8398; }
.cc-cm-metric strong { font-size: 16px; color: #eceff6; }
.cc-cm-insights { list-style: none; padding: 0; margin: 0 auto; max-width: 720px; text-align: left; }
.cc-cm-insights li { padding: 9px 13px; margin-bottom: 7px; background: rgba(79,155,217,0.10); border-left: 3px solid #4f9bd9; border-radius: 4px; color: #dde5f1; font-size: 13px; line-height: 1.45; }
@media (max-width: 640px) { .cc-cm-metric { min-width: 70px; } .cc-cm-verdict { font-size: 19px; } }


/* Focus visibility + reduced motion (EQIL a11y pass 2026-07-28) */
.lumibec-panel select:focus-visible,
.lumibec-panel input:focus-visible,
#nextPeriodBtn:focus-visible,
#undoBtn:focus-visible {
    outline: 2px solid currentColor;
    outline-offset: 2px;
}
@media (prefers-reduced-motion: reduce) {
    .lumibec-panel, #nextPeriodBtn, #undoBtn { transition: none; animation: none; }
}

