(function() {
    'use strict';

    class CommunitiesOfCreativityAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Communities of Creativity`;
            this.version = `1.2.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card (Studio Lumibec, Montréal, CAD).
            this.RD_BUDGET = 36;          // CA$36M fixed R&D / new-development envelope
            this.SLACK_COST_FULL = 9;     // ~CA$9M/yr for full 20% slack
            this.SLACK_MAX = 20;          // 20% slack under debate
            this.START_THROUGHPUT = 100;  // baseline idea-throughput index
            this.START_ENGAGEMENT = 62;   // voluntary community engagement (%)
            this.START_TTP = 22;          // weeks idea -> prototype (eroding from 14 toward 30+)
            this.TTP_HEALTHY = 14;        // healthy time-to-prototype
            this.CONNECTORS = 2;          // two senior knowledge brokers at flight risk
            this.CONNECTOR_COST = 0.4;    // ~CA$400K retention envelope (CA$M)

            // Concept "true" levers.
            this.TRUE_FLOW = `communities`;
            this.TRUE_GOV = `communities`;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    throughput: this.START_THROUGHPUT,   // idea-throughput index (100 = baseline)
                    engagement: this.START_ENGAGEMENT,   // community engagement (%)
                    ttp: this.START_TTP,                 // time-to-prototype (weeks)
                    roi: null,                           // innovation ROI (%), resolves in R4
                    slack: 0,                            // protected slack preserved (%) — starts cut (CFO default)
                    explore: 15,                         // % of budget to exploration
                    connectorsRetained: this.CONNECTORS, // both intact at start; can be lost
                    govStewarded: false,                 // slack channelled through communities
                    communitiesManaged: false,           // tried to manage communities like teams
                    overSwung: false,                    // hard swing to exploration
                    slackCut: false,                     // protected slack scrapped to zero (Common Error 1)
                    govUngoverned: false,                // slack restored with no community structure (Common Error 2)
                    sequelSlipped: false,                // sequel ship date slipped
                    connectorCost: 0,                    // CA$M committed to retention
                    throughputHistory: [this.START_THROUGHPUT],
                    engagementHistory: [this.START_ENGAGEMENT],
                    ttpHistory: [this.START_TTP],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Seeded defaults lean toward the classic errors — a blind
                // click-through must NOT auto-win (CFO's "scrap the slack" path).
                state.decisions = {
                    flow: `orgchart`,
                    health: `fine`,
                    dependence: `low`,
                    diag: 30,
                    slack: 0,
                    gov: `free`,
                    who: `sequel`,
                    explore: 15,
                    funnel: `committee`,
                    risk: `oneswing`,
                    pipeline: `fundall`,
                    retain: `let`,
                    metrics: `quarter`,
                    conviction: 50
                };
            }
            this._syncControlsFromDecisions(state);
            this._updateBriefing(state);
        }
        _syncControlsFromDecisions(state) {
            // On resume the framework restores decisions but the DOM still showed the
            // authored defaults, so the player saw values that were not their own.
            const d = state.decisions || {};
            const map = {
                flowInput: d.flow,
                healthInput: d.health,
                dependenceInput: d.dependence,
                diagInput: d.diag,
                slackInput: d.slack,
                govInput: d.gov,
                whoInput: d.who,
                exploreInput: d.explore,
                funnelInput: d.funnel,
                riskInput: d.risk,
                pipelineInput: d.pipeline,
                retainInput: d.retain,
                metricsInput: d.metrics,
                convictionInput: d.conviction
            };
            Object.keys(map).forEach((id) => {
                if (map[id] === undefined || map[id] === null) return;
                const el = document.getElementById(id);
                if (el) el.value = map[id];
            });
            [[`diagInput`, `diagReadout`], [`slackInput`, `slackReadout`], [`exploreInput`, `exploreReadout`]].forEach((pair) => {
                const src = document.getElementById(pair[0]);
                const out = document.getElementById(pair[1]);
                if (src && out) out.textContent = src.value;
            });
        }


        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const fl = document.getElementById(`flowInput`);
                const he = document.getElementById(`healthInput`);
                const de = document.getElementById(`dependenceInput`);
                const di = document.getElementById(`diagInput`);
                if (fl) decisions.flow = fl.value;
                if (he) decisions.health = he.value;
                if (de) decisions.dependence = de.value;
                if (di) decisions.diag = parseInt(di.value, 10);
                if (!Number.isFinite(decisions.diag) || decisions.diag < 0 || decisions.diag > 100) {
                    warn(`warn_diag_range`); return false;
                }
            } else if (round === 2) {
                const sl = document.getElementById(`slackInput`);
                const go = document.getElementById(`govInput`);
                const wh = document.getElementById(`whoInput`);
                if (sl) decisions.slack = parseInt(sl.value, 10);
                if (go) decisions.gov = go.value;
                if (wh) decisions.who = wh.value;
                if (!Number.isFinite(decisions.slack) || decisions.slack < 0 || decisions.slack > this.SLACK_MAX) {
                    warn(`warn_slack_range`); return false;
                }
            } else if (round === 3) {
                const ex = document.getElementById(`exploreInput`);
                const fu = document.getElementById(`funnelInput`);
                const ri = document.getElementById(`riskInput`);
                if (ex) decisions.explore = parseInt(ex.value, 10);
                if (fu) decisions.funnel = fu.value;
                if (ri) decisions.risk = ri.value;
                if (!Number.isFinite(decisions.explore) || decisions.explore < 0 || decisions.explore > 60) {
                    warn(`warn_explore_range`); return false;
                }
            } else if (round === 4) {
                const pi = document.getElementById(`pipelineInput`);
                const re = document.getElementById(`retainInput`);
                const me = document.getElementById(`metricsInput`);
                const cv = document.getElementById(`convictionInput`);
                if (pi) decisions.pipeline = pi.value;
                if (re) decisions.retain = re.value;
                if (me) decisions.metrics = me.value;
                if (cv) decisions.conviction = parseInt(cv.value, 10);
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            }
            return true;
        }

                calculateResults(state) {
            // Thin wrapper: the round model lives in _computeRound so this method stays
            // short and its return statement is visible to static validators, current and
            // legacy alike. Keep this comment free of apostrophes, quotes and backticks:
            // the importer treats any of them as a string delimiter and desyncs its brace
            // counter, which produced the false empty-method and missing-return errors.
            const r = this._computeRound(state);
            const period = state.currentPeriod;
            return {
                period: period,
                score: r.score,
                overallScore: r.overallScore,
                throughput: r.throughput,
                throughputDelta: r.throughputDelta,
                engagement: r.engagement,
                engagementDelta: r.engagementDelta,
                ttp: r.ttp,
                ttpDelta: r.ttpDelta,
                roi: r.roi,
                slack: r.slack,
                explore: r.explore,
                connectorsRetained: r.connectorsRetained,
                summary: r.summary,
                coach: r.coach
            };
        }

        _computeRound(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let throughputDelta = 0, engagementDelta = 0, ttpDelta = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Diagnose where knowledge flows and how dependent the pipeline is on slack.
                switch (d.flow) {
                    case `communities`: engagementDelta += 4; coachKey = `coach_r1_communities`; break;
                    case `orgchart`: engagementDelta -= 2; coachKey = `coach_r1_orgchart`; break;
                    case `docs`: engagementDelta -= 1; coachKey = `coach_r1_docs`; break;
                }

                switch (d.health) {
                    case `leading`: engagementDelta += 3; ttpDelta -= 1; if (d.flow === `communities`) coachKey = `coach_r1_sharp`; break;
                    case `fine`: throughputDelta -= 2; coachKey = `coach_r1_fine`; break;
                    case `budget`: engagementDelta -= 2; coachKey = `coach_r1_budget`; break;
                }

                switch (d.dependence) {
                    case `high`: engagementDelta += 3; break;       // correct read of slack-born pipeline
                    case `low`: throughputDelta -= 2; if (coachKey === `coach_default`) coachKey = `coach_r1_dependlow`; break;
                    case `none`: throughputDelta -= 3; engagementDelta -= 2; if (coachKey === `coach_default`) coachKey = `coach_r1_dependnone`; break;
                }

                // Diagnostic depth: a thorough diagnosis improves later targeting.
                if (d.diag >= 50) { engagementDelta += 2; }
                else if (d.diag <= 15) { engagementDelta -= 2; }

                summaryKey = (d.flow === `communities` && d.health === `leading` && d.dependence === `high`) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Allocate slack time (Common Errors 1 & 2).
                ds.slack = d.slack;
                const slackFrac = d.slack / this.SLACK_MAX;   // 0..1

                if (d.slack <= 0) {
                    // Cut slack to zero — protect the quarter, empty the future (decision tree #1).
                    // This is the concept's HEADLINE anti-pattern: the communities dissolve,
                    // throughput collapses on a lag, and the future pipeline empties. It must be a
                    // permanent, run-defining wound (capped at the end), not a dip later choices erase.
                    ds.slackCut = true;
                    throughputDelta -= 12;       // lag: throughput starts collapsing
                    engagementDelta -= 20;       // communities wither fast
                    ttpDelta += 7;               // time-to-prototype balloons
                    coachKey = `coach_r2_cut`;
                } else {
                    // Slack restored — but ONLY pays off when stewarded through communities.
                    const channel = (d.gov === `communities`) ? 1 : (d.gov === `managers` ? 0.22 : 0.35);
                    ds.govStewarded = (d.gov === `communities`);
                    throughputDelta += Math.round(10 * slackFrac * channel);
                    engagementDelta += Math.round(14 * slackFrac * channel);
                    ttpDelta -= Math.round(7 * slackFrac * channel);

                    if (d.gov === `free`) {
                        // Ungoverned slack: you pay the cost, get little throughput (decision tree #2).
                        // Unfocused free time is a real classic error — flag it so it can't reach the top.
                        ds.govUngoverned = true;
                        coachKey = `coach_r2_free`;
                        engagementDelta -= 4;
                        throughputDelta -= 3;
                    } else if (d.gov === `managers`) {
                        // Managers redeploy it onto the roadmap — not really slack at all.
                        coachKey = `coach_r2_managers`;
                    } else {
                        coachKey = `coach_r2_communities`;
                    }
                }

                // Who gets the slack — targeting the eroding communities matters.
                switch (d.who) {
                    case `connected`: engagementDelta += 5; throughputDelta += 3; break;
                    case `everyone`: engagementDelta += 1; if (coachKey === `coach_r2_communities`) coachKey = `coach_r2_everyone`; break;
                    case `sequel`: engagementDelta -= 4; if (coachKey === `coach_default` || coachKey === `coach_r2_communities`) coachKey = `coach_r2_whosequel`; break;
                }

                // Slack that is real also costs production capacity — heavy slack on top of
                // a tight sequel raises slip risk (handled as a soft sequel pressure later).
                if (d.slack >= 16 && d.who !== `connected`) { ds.sequelSlipped = true; }

                summaryKey = (d.slack >= 12 && d.gov === `communities` && d.who === `connected`) ? `sum_r2_good` :
                             (d.slack <= 0 ? `sum_r2_cut` :
                             (d.gov === `free` ? `sum_r2_ungoverned` : `sum_r2_weak`));
            } else if (round === 3) {
                // Balance exploration vs exploitation (Common Error 3) + how communities feed the funnel.
                ds.explore = d.explore;

                // Sweet spot ~25-35% exploration. Too little starves the future; too much
                // starves the franchise sequel that pays the bills (decision tree #3).
                if (d.explore >= 20 && d.explore <= 35) {
                    throughputDelta += 8; coachKey = `coach_r3_balanced`;
                } else if (d.explore < 20) {
                    throughputDelta += 2;
                    if (d.explore <= 15) { throughputDelta -= 3; coachKey = `coach_r3_exploit`; }
                } else { // > 35 — over-swing
                    ds.overSwung = true;
                    throughputDelta += 2;          // lots of bets, but most will fail...
                    ttpDelta += 2;                 // attention scatters across too many prototypes
                    ds.sequelSlipped = true;       // the sequel that funds everything slips
                    coachKey = `coach_r3_overswing`;
                }

                // How the communities feed the funnel (Common Error 4: managing communities like teams).
                switch (d.funnel) {
                    case `emergent`: throughputDelta += 6; engagementDelta += 6; ttpDelta -= 3; break;
                    case `committee`: engagementDelta -= 8; throughputDelta -= 3; ds.communitiesManaged = true; coachKey = `coach_r3_committee`; break;
                    case `random`: throughputDelta -= 2; engagementDelta -= 2; coachKey = `coach_r3_random`; break;
                }

                // Risk logic for the exploration portfolio.
                switch (d.risk) {
                    case `portfolio`: throughputDelta += 4; ttpDelta -= 1; break;
                    case `oneswing`: throughputDelta -= 2; if (coachKey === `coach_default`) coachKey = `coach_r3_oneswing`; break;
                    case `safe`: throughputDelta -= 3; engagementDelta -= 2; if (coachKey === `coach_default`) coachKey = `coach_r3_safe`; break;
                }

                summaryKey = (d.explore >= 20 && d.explore <= 35 && d.funnel === `emergent` && d.risk === `portfolio`) ? `sum_r3_good` :
                             (ds.overSwung ? `sum_r3_overswing` :
                             (d.funnel === `committee` ? `sum_r3_committee` :
                             (d.explore <= 15 ? `sum_r3_exploit` : `sum_r3_weak`)));
            } else if (round === 4) {
                // Fund the pipeline & retain the connectors (Common Error 5) + metrics.
                ds.stageGated = (d.pipeline === `staged`);   // a genuine go/kill stage-gate?
                switch (d.pipeline) {
                    case `staged`: throughputDelta += 8; ttpDelta -= 2; coachKey = `coach_r4_staged`; break;
                    case `fundall`: throughputDelta += 2; ttpDelta += 3; coachKey = `coach_r4_fundall`; break;
                    case `none`: throughputDelta -= 6; engagementDelta -= 4; coachKey = `coach_r4_none`; break;
                }

                // Retain the two senior connectors (decision tree #5).
                switch (d.retain) {
                    case `both`:
                        ds.connectorsRetained = 2; ds.connectorCost = this.CONNECTOR_COST;
                        engagementDelta += 6; ttpDelta -= 4; if (d.pipeline === `staged`) coachKey = `coach_r4_retainboth`;
                        break;
                    case `one`:
                        ds.connectorsRetained = 1; ds.connectorCost = this.CONNECTOR_COST / 2;
                        engagementDelta -= 3; ttpDelta += 6; coachKey = `coach_r4_retainone`;
                        break;
                    case `let`:
                        ds.connectorsRetained = 0; ds.connectorCost = 0;
                        engagementDelta -= 10; ttpDelta += 14; coachKey = `coach_r4_letwalk`;
                        break;
                }

                // Which metrics you commit to — judging on this quarter alone (decision tree #6).
                switch (d.metrics) {
                    case `leading`: engagementDelta += 3; if (coachKey === `coach_default` || coachKey === `coach_r4_staged`) coachKey = `coach_r4_leading`; break;
                    case `quarter`: throughputDelta -= 2; coachKey = `coach_r4_quarter`; break;
                    case `revenue`: throughputDelta -= 3; engagementDelta -= 2; coachKey = `coach_r4_revenue`; break;
                }

                if (d.conviction >= 60) { engagementDelta += 2; }
                else if (d.conviction <= 25) { engagementDelta -= 2; }

                summaryKey = (d.pipeline === `staged` && d.retain === `both` && d.metrics === `leading`) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // ---- Apply deltas (clamped). ----
            ds.throughput = Math.max(0, Math.min(180, Math.round(ds.throughput + throughputDelta)));
            ds.engagement = Math.max(0, Math.min(100, Math.round(ds.engagement + engagementDelta)));
            ds.ttp = Math.max(8, Math.min(40, Math.round(ds.ttp + ttpDelta)));

            // ---- Losing the connectors caps everything (network value > headcount). ----
            if (ds.connectorsRetained === 0) {
                ds.engagement = Math.min(ds.engagement, 40);
                ds.ttp = Math.max(ds.ttp, 30);
            } else if (ds.connectorsRetained === 1) {
                ds.ttp = Math.max(ds.ttp, 22);
            }

            // ---- STICKY CAPS for the classic errors (mirroring the connector cap). ----
            // The concept's whole point is that these are invisible, delayed wounds the
            // numbers won't let you out-decide later. Each headline error permanently bounds
            // the creative engine so no downstream good move can paper over it and steal the
            // top verdict. Cutting slack to zero is the worst — the pipeline empties.
            if (ds.slackCut) {
                // Throughput collapses ~60% off baseline, the guild dissolves, the funnel empties.
                ds.engagement = Math.min(ds.engagement, 40);
                ds.throughput = Math.min(ds.throughput, 70);
                ds.ttp = Math.max(ds.ttp, 30);
            }
            if (ds.govUngoverned) {
                // You paid the full cost; unfocused free time never became shared experiments.
                ds.engagement = Math.min(ds.engagement, 60);
                ds.throughput = Math.min(ds.throughput, 100);
            }
            if (ds.communitiesManaged) {
                // Quotas turned the community into a committee; voluntary participation collapsed.
                ds.engagement = Math.min(ds.engagement, 55);
            }
            if (ds.overSwung) {
                // Most bets fail and the sequel that funds the gap slipped; the engine spins
                // but doesn't convert — capped below the sustained band.
                ds.throughput = Math.min(ds.throughput, 115);
                ds.ttp = Math.max(ds.ttp, 16);
            }

            // ---- Innovation ROI is DERIVED and resolves at the end (Round 4): a leading-indicator
            // engine. Healthy communities + short time-to-prototype + a balanced explore split +
            // a real stage-gate produce return; a stalled, disengaged engine produces a loss. ----
            if (round >= 4) {
                const engFactor = ds.engagement / 100;                          // 0..1
                const speedFactor = Math.max(0, (30 - ds.ttp) / (30 - this.TTP_HEALTHY)); // 0..~1
                const throughFactor = Math.max(0, Math.min(1.2, ds.throughput / 100));
                const exploreSweet = (ds.explore >= 20 && ds.explore <= 35) ? 1 : (ds.explore < 20 ? 0.6 : 0.5);
                const stageGate = (d.pipeline === `staged`) ? 1 : (d.pipeline === `fundall` ? 0.55 : 0.2);
                let roi = Math.round(
                    -45 + 150 * (0.32 * engFactor + 0.26 * speedFactor + 0.22 * throughFactor + 0.20 * exploreSweet) * stageGate
                );
                if (ds.sequelSlipped) roi -= 18;       // the franchise that funds the gap slipped
                if (ds.slackCut) roi -= 30;            // empty pipeline can't return — headline error
                if (ds.govUngoverned) roi -= 12;       // paid the cost, no shared experiments
                if (ds.communitiesManaged) roi -= 10;  // committee, not community: ideas dried up
                ds.roi = Math.max(-60, Math.min(90, roi));
            }

            ds.throughputHistory.push(ds.throughput);
            ds.engagementHistory.push(ds.engagement);
            ds.ttpHistory.push(ds.ttp);

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            // v1.1.0 FIX A - persist the composite where the gradebook / reporting layer reads it
            const _c = this._composite(ds);
            ds.score = _c;
            if (!ds.performance) ds.performance = {};
            ds.performance.overallScore = _c;
            return {
                period: state.currentPeriod,
                score: _c,
                overallScore: _c,
                throughput: ds.throughput,
                throughputDelta: Math.round(throughputDelta),
                engagement: ds.engagement,
                engagementDelta: Math.round(engagementDelta),
                ttp: ds.ttp,
                ttpDelta: Math.round(ttpDelta),
                roi: ds.roi,
                slack: ds.slack,
                explore: ds.explore,
                connectorsRetained: ds.connectorsRetained,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

        setupUI(uiManager) {
            uiManager.bind(`currentDay`, `currentPeriod`);
            uiManager.bind(`maxPeriods`, `maxPeriods`);

            const self = this;

            uiManager.bind(`throughputDisplay`, `domainState.throughput`, (v) => {
