        getChartData(state) {
            const ds = (state && state.domainState) || {};
            const _engagementHistory = ds.engagementHistory || [];
            const _throughputHistory = ds.throughputHistory || [];
            const _ttpHistory = ds.ttpHistory || [];
            const labels = _throughputHistory.map((_, i) => (i === 0 ? window.mySimulation.t(`chart_start`) : `R` + i));
            return {
                pipelineChart: {
                    labels: labels,
                    datasets: [
                        { data: _throughputHistory },
                        { data: _engagementHistory },
                        { data: _ttpHistory }
                    ]
                }
