        _composite(ds) {
            // v1.1.0 - verbatim replica of the getPerformanceSummary composite (weights unchanged).
            const throughput = Math.round(ds.throughput);
            const engagement = Math.round(ds.engagement);
            const ttp = Math.round(ds.ttp);
            const roi = (ds.roi === null || ds.roi === undefined) ? 0 : Math.round(ds.roi);
            const speedScore = Math.max(0, Math.min(100, ((40 - ttp) / (40 - this.TTP_HEALTHY)) * 100));
            const roiScore = Math.max(0, Math.min(100, (roi + 60) / 1.5));
            const throughScore = Math.max(0, Math.min(100, throughput * 0.8 + 10));
            return Math.round(throughScore * 0.28 + engagement * 0.27 + speedScore * 0.22 + roiScore * 0.23);
        }

        formatCompletionMessage(summary) {
            // v1.1.0 FIX B - localized innovation-board debrief scorecard (was: framework default that
            // discarded score, tier, targets and insights).
            const t = (window.mySimulation && typeof window.mySimulation.t === 'function')
                ? window.mySimulation.t.bind(window.mySimulation)
                : function (k) { return k; };
            summary = summary || {};
            const score = (summary.composite != null) ? summary.composite : (summary.score != null ? summary.score : 0);
            const verdict = summary.gradeKey ? t(summary.gradeKey) : (summary.performance || '');
            const insights = summary.insights || [];
            const chip = function (ok, label) {
                return '<div class="cc-cm-target ' + (ok ? 'cc-cm-met' : 'cc-cm-missed') + '">'
                    + '<span class="cc-cm-tick">' + (ok ? '✓' : '✗') + '</span><span>' + label + '</span></div>';
            };
            const targets = ''
                + chip(!!summary.engineHealthy, t('tgt_engine'))
                + chip(!!summary.fastPipeline, t('tgt_fast'))
                + chip(!!summary.profitable, t('tgt_profit'))
                + chip(!!summary.connectorsHeld, t('tgt_connectors'))
                + chip(!!summary.cleanRun, t('tgt_clean'));
            const metric = function (label, val) {
                return '<div class="cc-cm-metric"><span>' + label + '</span><strong>' + val + '</strong></div>';
            };
            const nz = function (v) { return (v != null) ? v : '-'; };
            const metrics = ''
                + metric(t('kpi_throughput'), nz(summary.throughput))
                + metric(t('kpi_engagement'), nz(summary.engagement) + '%')
                + metric(t('kpi_ttp'), nz(summary.ttp) + ' wks')
                + metric(t('kpi_roi'), nz(summary.roi) + '%');
            const items = insights.map(function (s) { return '<li>' + s + '</li>'; }).join('');
            return ''
                + '<div class="cc-cm">'
                +   '<div class="cc-cm-heading">' + t('comp_heading') + '</div>'
                +   '<div class="cc-cm-verdict">' + verdict + '</div>'
                +   '<div class="cc-cm-score">' + t('comp_score_label') + ': <strong>' + score + '</strong> / 100</div>'
                +   '<div class="cc-cm-sub">' + t('comp_targets_heading') + '</div>'
                +   '<div class="cc-cm-targets">' + targets + '</div>'
                +   '<div class="cc-cm-metrics">' + metrics + '</div>'
                +   (items ? '<ul class="cc-cm-insights">' + items + '</ul>' : '')
                + '</div>';
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const t = (window.mySimulation && typeof window.mySimulation.t === 'function') ? window.mySimulation.t.bind(window.mySimulation) : function (k) { return k; };
            const ds = window.mySimulation.state.domainState;
            const throughput = Math.round(ds.throughput);
            const engagement = Math.round(ds.engagement);
            const ttp = Math.round(ds.ttp);
            const roi = (ds.roi === null || ds.roi === undefined) ? 0 : Math.round(ds.roi);
            const connectors = ds.connectorsRetained;

            // Composite of the four-engine: throughput, engagement, speed, ROI.
            const speedScore = Math.max(0, Math.min(100, ((40 - ttp) / (40 - this.TTP_HEALTHY)) * 100));
            const roiScore = Math.max(0, Math.min(100, (roi + 60) / 1.5));   // -60..+90 -> 0..100
            const throughScore = Math.max(0, Math.min(100, throughput * 0.8 + 10));
            const composite = Math.round(
                throughScore * 0.28 + engagement * 0.27 + speedScore * 0.22 + roiScore * 0.23
            );

            const engineHealthy = engagement >= 60;
            const fastPipeline = ttp <= 18;
            const profitable = roi >= 20;
            const connectorsHeld = connectors >= 2;

            // Any of the five concept "Common Errors" committed at all? The top verdict
            // requires a clean run — a single headline error must bar "Creative Engine Sustained".
            const noClassicError = !ds.slackCut && !ds.govUngoverned && !ds.overSwung &&
                                   !ds.communitiesManaged && connectorsHeld;

            let pattern = `mixed`;
            if (ds.slackCut || (ds.slack <= 0 && engagement < 45)) pattern = `cutslack`;
            else if (connectors === 0) pattern = `lostconnectors`;
            else if (ds.overSwung) pattern = `overswing`;
            else if (ds.communitiesManaged) pattern = `managed`;
            else if (ds.govUngoverned) pattern = `ungoverned`;
            else if (engineHealthy && fastPipeline && profitable) pattern = `ambidextrous`;

            // v1.1.0 FIX C - tier resolved to an i18n key and localized via t() (was hardcoded English).
            let perfKey = `grade_emptied`;
            if (noClassicError && ds.stageGated && engineHealthy && fastPipeline && profitable && composite >= 75) perfKey = `grade_sustained`;
            else if (noClassicError && engineHealthy && composite >= 60) perfKey = `grade_protected`;
            else if (pattern === `cutslack`) perfKey = `grade_cutslack`;
            else if (pattern === `lostconnectors`) perfKey = `grade_connectors`;
            else if (pattern === `overswing`) perfKey = `grade_overswing`;
            else if (pattern === `managed`) perfKey = `grade_managed`;
            else if (pattern === `ungoverned`) perfKey = `grade_ungoverned`;
            else if (composite >= 55) perfKey = `grade_mixed`;
            const performance = t(perfKey);

            const insights = [];
            if (pattern === `ambidextrous` && engineHealthy && profitable) insights.push(window.mySimulation.t(`insight_ambidextrous`));
            else if (pattern === `cutslack`) insights.push(window.mySimulation.t(`insight_cutslack`));
            else if (pattern === `lostconnectors`) insights.push(window.mySimulation.t(`insight_connectors`));
            else if (pattern === `overswing`) insights.push(window.mySimulation.t(`insight_overswing`));
            else if (pattern === `managed`) insights.push(window.mySimulation.t(`insight_managed`));
            else if (pattern === `ungoverned`) insights.push(window.mySimulation.t(`insight_ungoverned`));
            else insights.push(window.mySimulation.t(`insight_mixed`));

            if (connectors === 0) insights.push(window.mySimulation.t(`insight_connectors`));
            if (engagement < 45) insights.push(window.mySimulation.t(`insight_engagement_low`));
            if (ttp >= 28) insights.push(window.mySimulation.t(`insight_ttp_high`));
            if (ds.sequelSlipped) insights.push(window.mySimulation.t(`insight_sequel`));
            if (roi < 0) insights.push(window.mySimulation.t(`insight_roi_negative`));

            return {
                gradeKey: perfKey,
                score: composite,
                cleanRun: noClassicError,
                stageGated: !!ds.stageGated,
                throughput: throughput,
                engagement: engagement,
                ttp: ttp,
                roi: roi,
                connectors: connectors,
                engineHealthy: engineHealthy,
                fastPipeline: fastPipeline,
                profitable: profitable,
                connectorsHeld: connectorsHeld,
                pattern: pattern,
                composite: composite,
                overallScore: composite,
                totalScore: composite,
                performance: performance,
                performanceLabel: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.connectorsRetained === 0) return window.mySimulation.t(`hint_connectors`);
            if (ds.slack <= 0 && state.currentPeriod >= 2) return window.mySimulation.t(`hint_cutslack`);
            if (ds.engagement < 40) return window.mySimulation.t(`hint_engagement`);
            if (ds.communitiesManaged && ds.engagement < 50) return window.mySimulation.t(`hint_managed`);
            if (ds.overSwung) return window.mySimulation.t(`hint_overswing`);
            if (ds.ttp >= 28) return window.mySimulation.t(`hint_ttp`);
            if (ds.engagement >= 65 && ds.ttp <= 16 && ds.throughput >= 110) return window.mySimulation.t(`hint_strong`);
            return null;
        }

        getHistoryTableConfig() {
            return [
                { key: `period`, label: `Round`, i18nKey: `col_round` },
                { key: `results.summary`, label: `Move`, i18nKey: `col_move` },
                { key: `results.throughput`, label: `Throughput`, i18nKey: `col_throughput`, formatter: (v) => `${Math.round(v)}` },
                { key: `results.engagement`, label: `Engagement`, i18nKey: `col_engagement`, formatter: (v) => `${Math.round(v)}%` },
                { key: `results.ttp`, label: `Time-to-Prototype`, i18nKey: `col_ttp`, formatter: (v) => `${Math.round(v)}w` },
                { key: `results.connectorsRetained`, label: `Connectors`, i18nKey: `col_connectors`, formatter: (v) => `${Math.round(v)}/2` }
            ];
        }

        getPresets() { return null; }

        _updateBriefing(state) {
            const period = (state && state.currentPeriod) || 1;
            const finished = period > this.ROUNDS.length;
            const idx = Math.min(period - 1, this.ROUNDS.length - 1);
            const round = this.ROUNDS[idx];
            const t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : (k) => k;

            const titleEl = document.getElementById(`briefingTitle`);
            if (titleEl) titleEl.textContent = t(round.titleKey);
            const textEl = document.getElementById(`briefingText`);
            if (textEl) textEl.innerHTML = t(round.textKey);
            const nameEl = document.getElementById(`roundNameDisplay`);
            if (nameEl) nameEl.textContent = t(round.nameKey);
            const clockEl = document.getElementById(`clockDisplay`);
            if (clockEl) clockEl.textContent = t(round.clockKey);

            for (let i = 0; i < this.ROUNDS.length; i++) {
                const panel = document.getElementById(this.ROUNDS[i].panelId);
                if (panel) panel.style.display = (!finished && i === idx) ? `block` : `none`;
            }
            const btnRow = document.getElementById(`eqilBtnRow`);
            if (btnRow) btnRow.style.display = finished ? `none` : ``;
        }

